import{_ as a,a as s,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 单元 3 复习与自测 · 第67–72课","description":"L49–L72 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 3 复习与自测 · 第67–72课","description":"L49–L72 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-03/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 3 复习与自测","summary":"L49–L72 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第58–66课","link":"/life/english/new-concept/book-2/unit-03/review-part-02"},"next":{"text":"第二册：实践与进步 · 单元 4：综合叙事与自主表达","link":"/life/english/new-concept/book-2/unit-04/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第58–66课","link":"/life/english/new-concept/book-2/unit-03/review-part-02"},"next":{"text":"第二册：实践与进步 · 单元 4：综合叙事与自主表达","link":"/life/english/new-concept/book-2/unit-04/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/review-part-03.md","filePath":"life/english/new-concept/book-2/unit-03/review-part-03.md"}'),n={name:"life/english/new-concept/book-2/unit-03/review-part-03.md"};function r(i,e,l,p,h,d){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-单元-3-复习与自测-·-第67–72课" tabindex="-1">第二册：实践与进步 · 单元 3 复习与自测 · 第67–72课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-3-复习与自测-·-第67–72课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 3 复习与自测 · 第67–72课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-03/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-67-·-完成进行时与持续活动" tabindex="-1">Lesson 67 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-67-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 67 · 完成进行时与持续活动 {#lesson-67-·-完成进行时与持续活动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The scientists have been monitoring the volcano since March.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>选 since/for：They have been observing it ___ March.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> since</p><p><strong>解析：</strong> March 是时间起点。</p></details><p><strong>表达迁移：</strong> 写一段科学观察简报，给出监测时段、一项发现和仍不确定的信息。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The scientists have been monitoring the volcano since March. They have recorded a rise in ground temperature. The report does not give an exact eruption date.</p><p>第一句的组织方式：have been monitoring 是完成进行时，since March 给起点；scientists 是复数主语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：since three months 不合常用表达；用 for three months 或 since March。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-067">回看本课</a></p><h2 id="lesson-68-·-动名词与动词搭配" tabindex="-1">Lesson 68 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-68-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 68 · 动名词与动词搭配 {#lesson-68-·-动名词与动词搭配}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My neighbour insisted on helping me carry the boxes.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>填 help：She insisted on ___ me.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> helping</p><p><strong>解析：</strong> 介词 on 后接动名词。</p></details><p><strong>表达迁移：</strong> 写三句礼貌回应坚持帮忙的人：感谢、解释、替代安排。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My neighbour insisted on helping me carry the boxes. I thanked her but explained that the boxes were empty. We agreed to meet for tea later.</p><p>第一句的组织方式：insisted on 是谓语搭配，helping 为介词宾语；help me carry 中 carry 可不带 to。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：insist to help 应改为 insist on helping；avoid to answer 应为 avoid answering。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-068">回看本课</a></p><h2 id="lesson-69-·-不定式与目的" tabindex="-1">Lesson 69 · 不定式与目的 <a class="header-anchor" href="#lesson-69-·-不定式与目的" aria-label="Permalink to &quot;Lesson 69 · 不定式与目的 {#lesson-69-·-不定式与目的}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The learner was told to stop beside the yellow line.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>填 to/for：The learner was told ___ stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> tell somebody to do 的被动保留 to。</p></details><p><strong>表达迁移：</strong> 写一次操作失误复盘，交代指令、错误和纠正，不推断恶意。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The learner was told to stop beside the yellow line. She pressed the wrong pedal for a moment. The instructor used the dual controls and stopped the car.</p><p>第一句的组织方式：was told 是被动转述，to stop 是要求内容，beside the yellow line 为位置。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：brake 是刹车，break 是弄坏或休息；二者同音但拼写含义不同。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-069">回看本课</a></p><h2 id="lesson-70-·-分词修饰与逻辑主语" tabindex="-1">Lesson 70 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-70-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 70 · 分词修饰与逻辑主语 {#lesson-70-·-分词修饰与逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Waving a red flag, the steward guided the visitors away.</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>谁在挥旗：Waving a flag, the steward opened the gate?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The steward.</p><p><strong>解析：</strong> 分词状语默认与主句主语同指。</p></details><p><strong>表达迁移：</strong> 写三句现场处置，使用一个与主句同主语的分词短语。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Waving a red flag, the steward guided the visitors away. A loose animal had entered the ring. Everyone waited behind the barrier until it was led out.</p><p>第一句的组织方式：Waving 的执行者是 the steward；guided 是主句过去式，the visitors 是宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Waving a flag, the visitors were moved 会让逻辑主语变成游客，不一定符合想表达的意思。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-070">回看本课</a></p><h2 id="lesson-71-·-非真实条件句" tabindex="-1">Lesson 71 · 非真实条件句 <a class="header-anchor" href="#lesson-71-·-非真实条件句" aria-label="Permalink to &quot;Lesson 71 · 非真实条件句 {#lesson-71-·-非真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If the clock had not been repaired, it would have stopped that winter.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>补全：It would ___ stopped without repairs.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 过去假设结果结构为 would have done。</p></details><p><strong>表达迁移：</strong> 写一个历史设施得到维护的故事，再补一句未维护的假设后果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If the clock had not been repaired, it would have stopped that winter. The town paid for the work in autumn. It still rings every evening.</p><p>第一句的组织方式：if 从句 had not been repaired 为过去完成被动；主句 would have stopped 表未发生的过去结果。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：would stopped 缺少 have；过去反事实结果要用 would have stopped。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-071">回看本课</a></p><h2 id="lesson-72-·-分词修饰与逻辑主语" tabindex="-1">Lesson 72 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-72-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 72 · 分词修饰与逻辑主语 {#lesson-72-·-分词修饰与逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A car called Silver Finch completed three test runs.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>句中主句谓语是 called 还是 completed？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> completed</p><p><strong>解析：</strong> called 为后置定语，completed 承担主句谓语。</p></details><p><strong>表达迁移：</strong> 介绍一台自拟名称的测试设备，给出测试数量和下一步决定。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A car called Silver Finch completed three test runs. Its fastest run ended early because of a tyre problem. The team postponed the record attempt.</p><p>第一句的组织方式：called Silver Finch 修饰 A car，completed 才是主句谓语，three test runs 为宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：A car called Silver Finch. 只是名词短语，不构成完整陈述句。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-072">回看本课</a></p>',52)])])}const u=a(n,[["render",r]]);export{g as __pageData,u as default};
